// 9媒体のRSSフィードURL
const feeds = [
  // Sports
  { url: 'https://www.espn.com/espn/rss/news', genre: 'sports', media_name: 'ESPN', country: 'United States', country_code: 'US' },
  { url: 'https://feeds.bbci.co.uk/sport/rss.xml', genre: 'sports', media_name: 'BBC Sport', country: 'United Kingdom', country_code: 'GB' },
  { url: 'https://e00-marca.uecdn.es/rss/futbol/futbol-internacional.xml', genre: 'sports', media_name: 'Marca', country: 'Spain', country_code: 'ES' },
  // Economy
  { url: 'https://feeds.bloomberg.com/markets/news.rss', genre: 'economy', media_name: 'Bloomberg', country: 'United States', country_code: 'US' },
  { url: 'https://www.reuters.com/rssFeed/businessNews', genre: 'economy', media_name: 'Reuters', country: 'United Kingdom', country_code: 'GB' },
  { url: 'https://www.nikkei.com/rss/economy.xml', genre: 'economy', media_name: 'Nikkei', country: 'Japan', country_code: 'JP' },
  // Gaming
  { url: 'https://feeds.feedburner.com/ign/all', genre: 'gaming', media_name: 'IGN', country: 'United States', country_code: 'US' },
  { url: 'https://kotaku.com/rss', genre: 'gaming', media_name: 'Kotaku', country: 'United States', country_code: 'US' },
  { url: 'https://www.4gamer.net/rss/index.xml', genre: 'gaming', media_name: '4Gamer', country: 'Japan', country_code: 'JP' }
];

return feeds.map(feed => ({ json: feed }));

// robots.txt チェック
const url = $input.first().json.url;
const origin = new URL(url).origin;
const robotsUrl = `${origin}/robots.txt`;

try {
  const response = await fetch(robotsUrl, {
    headers: { 'User-Agent': 'MIKATA-Bot/1.0' },
    signal: AbortSignal.timeout(5000)
  });

  if (response.ok) {
    const text = await response.text();
    const lines = text.split('\n');
    let isRelevantUA = false;

    for (const line of lines) {
      const trimmed = line.trim().toLowerCase();
      if (trimmed.startsWith('user-agent:')) {
        const ua = trimmed.replace('user-agent:', '').trim();
        isRelevantUA = ua === '*' || ua === 'mikata-bot';
      }
      if (isRelevantUA && trimmed.startsWith('disallow:')) {
        const path = trimmed.replace('disallow:', '').trim();
        if (path === '/' || path === '/*') {
          return [{ json: { ...($input.first().json), blocked: true } }];
        }
      }
    }
  }
} catch (e) {
  // robots.txt not available, proceed
}

return [{ json: { ...($input.first().json), blocked: false } }];

// RSS XMLをパースして記事アイテムを抽出
const items = $input.all();
const results = [];

for (const item of items) {
  const xml = item.json.data || '';
  const genre = item.json.genre;
  const media_name = item.json.media_name;
  const country = item.json.country;
  const country_code = item.json.country_code;

  // Simple XML item extraction
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  let count = 0;

  while ((match = itemRegex.exec(xml)) !== null && count < 5) {
    const itemXml = match[1];
    const titleMatch = itemXml.match(/<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/i);
    const linkMatch = itemXml.match(/<link[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/link>/i);

    if (titleMatch && linkMatch) {
      results.push({
        json: {
          title: titleMatch[1].trim(),
          url: linkMatch[1].trim(),
          media_name,
          country,
          country_code,
          genre
        }
      });
      count++;
    }
  }
}

return results;

// 政治フィルタ（キーワードブラックリスト）
const politicsKeywords = [
  '選挙', '政党', '大統領', '首相', '議会', '政権', '与党', '野党',
  '国会', '内閣', '参議院', '衆議院', '投票', '候補者',
  'election', 'president', 'congress', 'parliament', 'senate',
  'democrat', 'republican', 'political', 'politician', 'prime minister',
  'legislation', 'referendum', 'ballot', 'campaign',
  'gobierno', 'elecciones', 'parlamento', 'partido'
];

const items = $input.all();
const filtered = items.filter(item => {
  const title = (item.json.title || '').toLowerCase();
  return !politicsKeywords.some(kw => title.includes(kw.toLowerCase()));
});

return filtered;

// 2段重複検出（URL hash + content hash）
const crypto = require('crypto');
const items = $input.all();
const seen = new Set();
const unique = [];

for (const item of items) {
  const urlHash = crypto.createHash('sha256').update(item.json.url).digest('hex');
  const contentHash = crypto.createHash('sha256')
    .update(`${item.json.title}|${item.json.media_name}`)
    .digest('hex');

  const key = `${urlHash}|${contentHash}`;
  if (!seen.has(urlHash) && !seen.has(contentHash)) {
    seen.add(urlHash);
    seen.add(contentHash);
    unique.push(item);
  }
}

return unique;

// ジャンル別にソースをグループ化して記事生成APIへ送信
const items = $input.all();
const groups = {};

for (const item of items) {
  const genre = item.json.genre;
  if (!groups[genre]) groups[genre] = [];
  groups[genre].push(item.json);
}

const results = [];
for (const [genre, sources] of Object.entries(groups)) {
  // 各ジャンルから2-4件のソースをまとめて1記事に
  const batch = sources.slice(0, 4);
  if (batch.length >= 2) {
    results.push({
      json: {
        sources: batch,
        genre: genre
      }
    });
  }
}

return results;
